SELECT ss.ss_sold_date_sk, ss.ss_sold_time_sk, ss.ss_item_sk, ss.ss_customer_sk, ss.ss_store_sk, ss.ss_promo_sk, ss.ss_quantity, ss.ss_sales_price, ss.ss_ext_sales_price, ss.ss_ext_discount_amt, (ss.ss_ext_sales_price - ss.ss_ext_discount_amt) AS net_sales, CASE WHEN p.p_discount_active = 'N' THEN p.p_cost * 0.9 ELSE p.p_cost END AS adjusted_promo_cost, CASE WHEN p.p_channel_email = 'N' THEN 'Email' WHEN p.p_channel_tv = 'N' THEN 'TV' WHEN p.p_channel_radio = 'N' THEN 'Radio' ELSE 'Other' END AS primary_channel, (ss.ss_net_paid_inc_tax - ss.ss_ext_tax) AS net_paid_ex_tax, (ss.ss_net_profit / nullif(ss.ss_net_paid, 0)) * 100 AS profit_pct FROM store_sales AS ss JOIN promotion AS p ON ss.ss_promo_sk = p.p_promo_sk WHERE ss.ss_sold_date_sk BETWEEN 2451093 AND 2452599 AND p.p_discount_active = 'N'
